{
  global:
    JNI_OnLoad;
    Java_com_westlake_engine_*;
    /* Internal art:: symbols needed by our .so itself.
       They're still isolated from the phone's ART because
       dlopen with RTLD_LOCAL (default for System.loadLibrary)
       doesn't make these visible to other .so files. */
    _ZN3art*;
    _ZNK3art*;
    /* [DAYU600] cmsg FD-passing stubs referenced via dynamic reloc by the runtime;
       must be exported so the in-.so dynamic relocation resolves (more specific than
       the _ZN7android* local pattern below, so these win). */
    _ZN7android4base24SendFileDescriptorVector*;
    _ZN7android4base27ReceiveFileDescriptorVector*;
  local:
    /* Hide everything else (libc++, android-base, etc.) */
    _ZNSt*;
    _ZN7android*;
};
